"""Standard DB-API transaction completion and durable SQL receipt replay."""
import pymysql


def settle_transaction(conn,commit):
    try:
        if type(commit)is not bool:raise ValueError('explicit commit or rollback decision required')
        if commit:conn.commit()
        else:conn.rollback()
    finally:conn.close()


def apply_once(connect,operation_id,amount,max_attempts=3):
    if type(max_attempts)is not int or max_attempts<1:
        raise ValueError('positive integer attempt limit required')
    for attempt in range(max_attempts):
        conn=connect()
        try:
            conn.begin()
            with conn.cursor()as cursor:
                cursor.execute('SELECT balance FROM drain_accounts WHERE id=1 FOR UPDATE')
                row=cursor.fetchone()
                if row is None:raise ValueError('account missing')
                cursor.execute('SELECT delta,balance FROM drain_receipts WHERE operation_id=%s',(operation_id,))
                receipt=cursor.fetchone()
                if receipt is not None:
                    if receipt[0]!=amount:raise ValueError('operation id conflicts with existing amount')
                    conn.commit();return receipt[1]
                balance=row[0]+amount
                cursor.execute('UPDATE drain_accounts SET balance=%s WHERE id=1',(balance,))
                cursor.execute('INSERT INTO drain_receipts(operation_id,delta,balance) VALUES(%s,%s,%s)',(operation_id,amount,balance))
            conn.commit();return balance
        except pymysql.err.OperationalError as error:
            try:conn.rollback()
            except pymysql.Error:pass
            if error.args[0]not in(1205,1213,2006,2013,9007)or attempt+1==max_attempts:raise
        except BaseException:
            try:conn.rollback()
            except pymysql.Error:pass
            raise
        finally:conn.close()
