def linux_child_guard(expected_parent):
 if not sys.platform.startswith('linux'):raise OSError('ENVIRONMENT_UNAVAILABLE: isolated mysqld requires Windows Job or Linux parent-death signal')
 libc=ctypes.CDLL(None,use_errno=True)
 libc.prctl.restype=ctypes.c_int
 libc.prctl.argtypes=[ctypes.c_int,ctypes.c_ulong,ctypes.c_ulong,ctypes.c_ulong,ctypes.c_ulong]
 # Set before exec; then close the race where our parent exited before prctl.
 if libc.prctl(1,int(signal.SIGKILL),0,0,0)!=0:raise OSError(ctypes.get_errno(),'ENVIRONMENT_UNAVAILABLE: PR_SET_PDEATHSIG failed')
 observed=ctypes.c_int()
 if libc.prctl(2,ctypes.addressof(observed),0,0,0)!=0 or observed.value!=signal.SIGKILL:raise OSError('ENVIRONMENT_UNAVAILABLE: parent-death signal verification failed')
 if os.getppid()!=expected_parent:os.kill(os.getpid(),signal.SIGKILL)

@contextlib.contextmanager
def process(args,root,name,limit=240):
 log=(root/(name+'.log')).open('wb');job=None;stop=threading.Event();stat={'peak_rss':0};proc=None;thread=None
 try:
  expected_parent=os.getpid()
  kw={'creationflags':subprocess.BELOW_NORMAL_PRIORITY_CLASS} if os.name=='nt' else {'start_new_session':True,'preexec_fn':lambda:linux_child_guard(expected_parent)}
  try:proc=subprocess.Popen(args,stdout=log,stderr=log,cwd=root,env={**os.environ,'TMPDIR':str(root/'native-tmp')},**kw)
  except subprocess.SubprocessError as exc:raise FileNotFoundError('ENVIRONMENT_UNAVAILABLE: Linux mysqld parent-death guard could not be established') from exc
  if os.name=='nt':constrain(proc);job=child_job(proc)
  start=time.monotonic()
  def kill():
   if proc.poll() is None:
    if os.name=='nt':proc.kill()
    else:os.killpg(proc.pid,signal.SIGKILL)
  def monitor():
   while not stop.wait(.03):
    if proc.poll() is not None:return
    try:
     if os.name=='nt':memory=rss(proc.pid)
     else:
      fields=pathlib.Path('/proc/'+str(proc.pid)+'/status').read_text().splitlines()
      rss_line=next((x for x in fields if x.startswith('VmRSS:')),None)
      if rss_line is None:
       state=next((x.split()[1] for x in fields if x.startswith('State:')),None)
       if state in ('Z','X','x') or proc.poll() is not None:return
       # Linux can release mm before the task state becomes Z; allow only a bounded exit transition.
       for _ in range(30):
        if stop.wait(.01) or proc.poll() is not None:return
        try:current=pathlib.Path('/proc/'+str(proc.pid)+'/status').read_text().splitlines()
        except FileNotFoundError:return
        state=next((x.split()[1] for x in current if x.startswith('State:')),None)
        if state in ('Z','X','x'):return
        rss_line=next((x for x in current if x.startswith('VmRSS:')),None)
        if rss_line is not None:break
       if rss_line is None:raise OSError('ENVIRONMENT_UNAVAILABLE: MySQL VmRSS unavailable for 300ms')
      memory=int(rss_line.split()[1])*1024
     stat['peak_rss']=max(stat['peak_rss'],memory)
     if memory>384*1048576 or time.monotonic()-start>limit:raise RuntimeError('384MiB RSS / wall-time limit')
    except Exception as exc:
     if proc.poll() is None:stat['guard_error']=repr(exc);kill()
     return
  thread=threading.Thread(target=monitor,daemon=True);thread.start()
  yield proc
 finally:
  stop.set()
  if proc is not None:
   if proc.poll() is None:
    if os.name=='nt':proc.terminate()
    else:os.killpg(proc.pid,signal.SIGTERM)
   try:proc.wait(timeout=5)
   except subprocess.TimeoutExpired:
    if os.name=='nt':proc.kill()
    else:os.killpg(proc.pid,signal.SIGKILL)
    proc.wait(timeout=4)
  if thread:thread.join(timeout=2)
  if job:ctypes.windll.kernel32.CloseHandle(job)
  log.close()
  if proc:print(name,'PID',proc.pid,'stopped',proc.poll() is not None,'peak RSS',stat['peak_rss'])
  if stat.get('guard_error'):raise RuntimeError(stat)

def execute(conn,query,args=None):
 with conn.cursor() as c:c.execute(query,args);return c.fetchall()

