   assert sys.platform.startswith('linux') and hashlib.sha256(pathlib.Path(exe).resolve().read_bytes()).hexdigest()=='378b4f975414111d532438368c6d5e257a415bdcc4e897009bbbb15c214e33ab','Native empty-template optimization requires exact reviewed MySQL8.4.13 binary'
