      state={'identity':execute(rootconn,'SELECT CURRENT_USER()'),'accounts':execute(rootconn,'SELECT User,Host,plugin,account_locked,password_expired FROM mysql.user ORDER BY User,Host'),'root_grants':execute(rootconn,'SHOW GRANTS'),'schema_names':execute(rootconn,'SHOW DATABASES')}
      assert json.dumps(state,sort_keys=True)==json.dumps(expected_state,sort_keys=True),'Native clone must preserve original initialized root/default accounts and grants with no business data'
      uuid=execute(rootconn,'SELECT @@server_uuid')[0][0];assert uuid!=template_expected['probe_uuid'],'Every native clone must generate a distinct owned server UUID'
      assert template_manifest(template)==template_expected['files'],'Native template is unchanged after cloning/startup'
      print('NATIVE_MYSQL_EMPTY_TEMPLATE_CLONE',json.dumps({'path':str(template),'manifest_sha256':template_expected['manifest_sha256'],'binary_sha256':template_expected['binary_sha256'],'new_uuid':uuid,'original_default_identity_and_grants_preserved':True,'business_schemas_absent':True}),flush=True)
     execute(rootconn,"CREATE DATABASE training CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci")
     execute(rootconn,'USE training')
     secret=secrets.token_hex(24)
     execute(rootconn,"CREATE USER 'student'@'127.0.0.1' IDENTIFIED BY %s",(secret,))
     def learner(privileges):
      execute(rootconn,"GRANT "+privileges+" ON training.* TO 'student'@'127.0.0.1'")
      return pymysql.connect(host='127.0.0.1',port=port,user='student',password=secret,database='training',charset='utf8mb4',autocommit=True,connect_timeout=2,read_timeout=3,write_timeout=3,local_infile=False)
     yield rootconn,learner
    finally:
     if rootconn:
      try:execute(rootconn,'SHUTDOWN')
      except pymysql.Error:pass
      rootconn.close()
     try:p.wait(timeout=5)
     except subprocess.TimeoutExpired:pass
  finally:
   with socket.socket() as s:assert s.connect_ex(('127.0.0.1',port))!=0,'owned MySQL port remained open'
   if template_expected is not None:assert template_manifest(template)==template_expected['files'],'Question execution must not mutate fixed empty native template'

