    index="KEY time_lookup(tenant_id,bucket,event_time,id)" if bucketed else "KEY time_lookup(event_time,tenant_id,id)"
    with conn.cursor() as cursor:cursor.execute("CREATE TABLE `"+table+"`("+columns+index+")")

def record_key(ordinal,seed,scatter):
    if type(ordinal) is not int or not 0<=ordinal<KEY_MASK or type(seed) is not int or not 0<=seed<(1<<64) or type(scatter) is not bool:
        raise ValueError("bounded ordinal/seed and boolean scatter flag required")
    if not scatter:return ordinal+1
    # An odd multiplier gives a permutation modulo2**62 for this fixed-seed laboratory ordinal domain.
    return (ordinal*0x27BB2EE687B0B0FD+seed)&KEY_MASK

def inspect_layout(conn,queries):
    native={}
    for name,request in queries.items():
        with conn.cursor() as cursor:
            cursor.execute(request['sql'],request.get('args'))
            native[name]={'columns':tuple(item[0] for item in (cursor.description or ())), 'rows':cursor.fetchall()}
    shares={}
    if 'regions' in native:
        sample=native['regions'];index={name.upper():i for i,name in enumerate(sample['columns'])};groups={}
        for row in sample['rows']:
            path='record' if row[index['IS_INDEX']]==0 else str(row[index['INDEX_NAME']]).lower()
            groups.setdefault(path,{})[int(row[index['REGION_ID']])]=int(row[index['WRITTEN_BYTES']] or 0)
        for path,regions in groups.items():
            total=sum(regions.values())
            shares[path]=None if total==0 else max(regions.values())/total
    return {'native':native,'write_max_share':shares}
