"""Observe actual supplied PyMySQL cursor results; no simulated SQL or replica state."""
import time

class NativeCursor:
    def __init__(self,owner,cursor):
        self.owner=owner;self.native=cursor;self.rows=();self.offset=0
    def __enter__(self):return self
    def __exit__(self,*args):self.native.close()
    def __getattr__(self,name):return getattr(self.native,name)
    def execute(self,sql,args=None):
        event={'sql':sql,'args':args,'rows':(),'columns':(),'state':'attempted','engine_before':None}
        self.owner.events.append(event)
        if self.owner.native.open:
            try:
                with self.owner.native.cursor() as observer:
                    observer.execute('SELECT @@session.tidb_isolation_read_engines')
                    event['engine_before']=observer.fetchone()[0]
            except Exception as error:
                event['state']='trusted_session_observation_failed'
                raise RuntimeError('Native SESSION observation failed before learner statement') from error
        start=time.monotonic()
        try:
            count=self.native.execute(sql,args)
            self.rows=tuple(self.native.fetchall()) if self.native.description else ()
            self.offset=0
            event.update({'rows':self.rows,'columns':tuple(item[0] for item in (self.native.description or ())), 'native_execute_fetch_seconds':time.monotonic()-start,'state':'completed'})
            return count
        except BaseException as error:
            event.update({'state':'native_error','native_error_type':type(error).__name__,'native_error_args':error.args})
            raise
    def fetchall(self):
        rows=self.rows[self.offset:];self.offset=len(self.rows);return rows
    def fetchone(self):
        if self.offset>=len(self.rows):return None
        row=self.rows[self.offset];self.offset+=1;return row
    def fetchmany(self,size=None):
        size=self.native.arraysize if size is None else size
        rows=self.rows[self.offset:self.offset+size];self.offset+=len(rows);return rows
    def __iter__(self):return iter(self.fetchall())

class NativeConnection:
    def __init__(self,connection):self.native=connection;self.events=[]
    def __getattr__(self,name):return getattr(self.native,name)
    def cursor(self,*args,**kwargs):return NativeCursor(self,self.native.cursor(*args,**kwargs))

