import re,time

def _table(name):
    if not isinstance(name,str) or not re.fullmatch(r"[A-Za-z_][A-Za-z0-9_]*",name):
        raise ValueError("unsafe unqualified table name")
    return "`"+name+"`"

def configure_replica(conn,table,replicas):
    name=_table(table)
    if isinstance(replicas,bool) or not isinstance(replicas,int) or not 0<=replicas<=2:
        raise ValueError("replicas must be an integer from zero through two")
    with conn.cursor() as cur:
        cur.execute("ALTER TABLE "+name+" SET TIFLASH REPLICA "+str(replicas))

def inspect_query(conn,sql,engine):
    if engine not in ("tikv","tiflash"):
        raise ValueError("unsupported explicit engine")
    with conn.cursor() as cur:
        cur.execute("SELECT @@session.tidb_isolation_read_engines")
        previous=cur.fetchone()[0]
        primary_error=None
        try:
            cur.execute("SET SESSION tidb_isolation_read_engines=%s",(engine,))
            cur.execute("EXPLAIN ANALYZE "+sql)
            plan=cur.fetchall()
            started=time.monotonic()
            cur.execute(sql)
            rows=cur.fetchall()
            return {"plan":plan,"rows":rows,"seconds":time.monotonic()-started}
        except BaseException as error:
            primary_error=error
            raise
        finally:
            if conn.open:
                try:cur.execute("SET SESSION tidb_isolation_read_engines=%s",(previous,))
                except Exception:
                    if primary_error is None:raise

def withdraw_replica(conn,table,dependent_tables):
    _table(table)
    if table in dependent_tables:
        raise ValueError("remaining TiFlash query dependency")
    configure_replica(conn,table,0)
