"""Native transaction telemetry and bounded entry reference; no fabricated timestamps."""
import concurrent.futures
import math
import re
import time


def native_transaction(conn, statements, hold_seconds=0):
    if not isinstance(statements, (list, tuple)) or not statements:
        raise ValueError('nonempty statement sequence required')
    if isinstance(hold_seconds, bool) or not isinstance(hold_seconds, (int, float)) or not math.isfinite(hold_seconds) or not 0 <= hold_seconds <= .1:
        raise ValueError('hold_seconds must be finite in [0,.1]')
    for item in statements:
        if not isinstance(item, dict) or not isinstance(item.get('sql'), str) or not item['sql'].strip():
            raise ValueError('each statement needs SQL')
        if item.get('args') is not None and not isinstance(item['args'], (tuple, list)):
            raise ValueError('args must be a sequence or None')
    rows=[]
    timestamps=[]
    try:
        conn.begin()
        with conn.cursor() as cursor:
            for item in statements:
                cursor.execute(item['sql'], item.get('args'))
                rows.append(cursor.fetchall() if cursor.description else ())
                cursor.execute('SELECT @@tidb_current_ts')
                timestamps.append(int(cursor.fetchone()[0]))
        if hold_seconds:
            time.sleep(hold_seconds)
        conn.commit()
        return {'rows':rows,'native_timestamps':timestamps}
    except BaseException:
        # A disconnected connection cannot be repaired by cleanup SQL. Preserve the first native error.
        if getattr(conn, 'open', False):
            try:
                conn.rollback()
            except Exception:
                pass
        raise


def report_window(before, after, transactions):
    deltas={component:{key:value-before[component].get(key,0) for key,value in after[component].items()} for component in ('tidb','pd')}
    def total(component, prefix, label=None):
        return sum(value for key,value in deltas[component].items() if key.split('{',1)[0]==prefix and (label is None or re.search(r'(?:\{|,)\s*'+re.escape(label)+r'\s*(?:,|\})',key)))
    count=total('tidb','pd_client_request_handle_requests_duration_seconds_count','type="tso"')
    seconds=total('tidb','pd_client_request_handle_requests_duration_seconds_sum','type="tso"')
    server_count=total('pd','pd_server_handle_tso_duration_seconds_count')
    server_seconds=total('pd','pd_server_handle_tso_duration_seconds_sum')
    batch_count=total('tidb','pd_client_request_handle_tso_batch_size_count')
    batch_sum=total('tidb','pd_client_request_handle_tso_batch_size_sum')
    return {'deltas':deltas,'transaction_count':transactions,'native_rpc_count':count,'native_rpc_seconds':seconds,'native_rpc_mean_seconds':seconds/count if count else None,'native_server_count':server_count,'native_server_seconds':server_seconds,'native_server_mean_seconds':server_seconds/server_count if server_count else None,'native_batch_count':batch_count,'native_batch_sum':batch_sum,'native_batch_mean':batch_sum/batch_count if batch_count else None}


def run_bounded(jobs,max_inflight):
    if not isinstance(jobs,(list,tuple)) or any(not callable(job) for job in jobs):
        raise ValueError('jobs must be callable sequence')
    if type(max_inflight) is not int or max_inflight<1:
        raise ValueError('max_inflight must be a positive integer')
    admitted=list(jobs[:max_inflight])
    with concurrent.futures.ThreadPoolExecutor(max_workers=max_inflight) as pool:
        results=list(pool.map(lambda job:job(),admitted))
    return {'accepted':results,'rejected':len(jobs)-len(admitted)}

